def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One run of `holder`'s `switchyard new` (or the entry point), every phase a recording stand-in on `t`."""
    import contextlib, dataclasses, shutil, tempfile
    from pathlib import Path as _P
    from types import SimpleNamespace
    calls: list = []
    printed: list = []
    tmp = _P(tempfile.mkdtemp(prefix="syrd425-")).resolve()
    answers = spec.get("answers", {})

    def recorder(*args, **kwargs):
        raise AssertionError(f"a stand-in phase never calls what it is handed: {args} {kwargs}")

    def show(line):
        printed.append(["print_func", norm(line)])

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items(), key=lambda kv: str(kv[0]))}
        if isinstance(value, _P):
            return "PATH " + norm(str(value))
        if isinstance(value, str):
            return value.replace(str(tmp), "TMP")
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        if isinstance(value, SimpleNamespace):
            return f"NAMESPACE {getattr(value, 'label', '?')}"
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            return {type(value).__name__: {f.name: norm(getattr(value, f.name)) for f in dataclasses.fields(value)}}
        if value is recorder:
            return "RECORDER"
        if value is show:
            return "PRINT recorder"
        if callable(value):
            return f"CALLABLE {getattr(value, '__module__', '?')}.{getattr(value, '__qualname__', '?')}"
        return f"OBJECT {type(value).__module__}.{type(value).__qualname__}"

    def note(seam, /, *args, **kwargs):
        reached.add(seam)
        calls.append([seam, norm(list(args)), norm(dict(kwargs))])

    class Stdout:
        def write(self, text):
            if text.strip():
                printed.append(["stdout", norm(text.rstrip("\n"))])
            return len(text)

        def flush(self):
            pass

    names = [*PHASES, *CONTINUATIONS.values(), "switchyard_new_command", "report_installed_release_version"]
    saved = {n: getattr(t, n) for n in names}

    def continuation(phase):
        kind = saved[CONTINUATIONS[phase]]
        return kind(**{f.name: f"{phase[1:]}.{f.name}" for f in dataclasses.fields(kind)})
    try:
        under = {n: getattr(holder, n) for n in FUNCTIONS}
        on_launcher = {}
        for n in PHASES:
            def phase(*args, _n=n, **kwargs):
                note(_n, *args, **kwargs)
                answer = answers.get(_n)
                if answer == "raise":
                    raise SystemExit(f"switchyard: syrd425 {_n} refused")
                if answer == "foreign":
                    return SimpleNamespace(label=f"{_n}'s foreign answer")
                if isinstance(answer, int) and not isinstance(answer, bool):
                    return answer
                return continuation(_n) if _n in CONTINUATIONS else 0
            on_launcher[n] = phase

        def dispatched(*args, **kwargs):
            note("switchyard_new_command", *args, **kwargs)
            return saved["switchyard_new_command"](*args, **kwargs)
        on_launcher["switchyard_new_command"] = dispatched
        on_launcher["report_installed_release_version"] = lambda *a, **k: note("report_installed_release_version", *a, **k)
        rebind = spec.get("rebind")
        if rebind == "NewProjectBoard":
            on_launcher[rebind] = type("SomeOtherContinuation", (), {})
        elif rebind == "_launch_new_project_panes":
            on_launcher[rebind] = lambda **kwargs: note("the rebound panes phase", **kwargs) or 42
        for n, f in on_launcher.items():
            setattr(t, n, f)
        place = lambda a: str(tmp) + a[1:] if isinstance(a, str) and a.startswith("@/") else a
        try:
            with contextlib.redirect_stdout(Stdout()):
                if spec["call"] == "command":
                    kwargs = {}
                    for k, v in spec["kwargs"].items():
                        if v == "recorder":
                            kwargs[k] = show if k == "print_func" else recorder
                        elif k == "role_clis":
                            kwargs[k] = [tuple(pair) for pair in v]
                        elif isinstance(v, str) and v.startswith(P + "/"):
                            kwargs[k] = _P(v)
                        else:
                            kwargs[k] = v
                    got = under["switchyard_new_command"](**kwargs)
                else:
                    got = t.switchyard_main([place(a) for a in spec["argv"]])
            result = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            result = {"raised": type(exc).__name__, "message": norm(str(exc))}
        return {"result": result, "calls": calls, "printed": printed}
    finally:
        for n, f in saved.items():
            setattr(t, n, f)
        shutil.rmtree(tmp)
