def test_the_module_loads_only_where_its_defaults_come_from() -> None:
    result = python("import sys, scripts.switchyard_new_command as m; "
                    "print(sorted(n for n in sys.modules if n.startswith('scripts.') and n != m.__name__))")
    check(result.returncode == 0 and result.stdout.strip() == str(DEFAULT_MODULES_LOADED),
          f"it imports on its own, loading only the modules its defaults come from (and what they load), never the launcher: "
          f"{result.stdout}{result.stderr[-400:]}")


def test_either_import_order_gives_one_object_and_the_launchers_defaults() -> None:
    for order in (("scripts.switchyard_new_command", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.switchyard_new_command")):
        result = python("import builtins, importlib, inspect, os; from pathlib import Path; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.switchyard_new_command as m; "
                        "p = inspect.signature(m.switchyard_new_command).parameters; "
                        "print(t.switchyard_new_command is m.switchyard_new_command, "
                        "all(p[k].default is getattr(t, v) for k, v in (('port_in_use', '_tcp_port_in_use'), ('socket_exists', '_path_exists'), "
                        "('runner', 'NO_RUNNER_INJECTED'), ('session_record_timeout', 'LAUNCH_SESSION_RECORD_TIMEOUT_SECONDS'), "
                        "('session_record_poll', 'LAUNCH_SESSION_RECORD_POLL_SECONDS'), ('layout_mode', 'LAYOUT_MODE_AUTO'))), "
                        "p['euid_getter'].default is os.geteuid and p['input_func'].default is builtins.input and p['print_func'].default is builtins.print "
                        "and p['home_base'].default == Path('/home'), "
                        "not hasattr(m, 'launcher') and not hasattr(m, '_NoRunnerInjected'))")
        check(result.stdout.strip() == "True True True True", f"{' then '.join(order)}: {result.stdout}{result.stderr[-600:]}")
    from scripts import first_run_auth, layout_modes, new_project_precheck, session_records
    check(m.NO_RUNNER_INJECTED is first_run_auth.NO_RUNNER_INJECTED and m.LAYOUT_MODE_AUTO is layout_modes.LAYOUT_MODE_AUTO
          and m._tcp_port_in_use is new_project_precheck._tcp_port_in_use and m._path_exists is new_project_precheck._path_exists
          and m.LAUNCH_SESSION_RECORD_TIMEOUT_SECONDS is session_records.LAUNCH_SESSION_RECORD_TIMEOUT_SECONDS
          and m.LAUNCH_SESSION_RECORD_POLL_SECONDS is session_records.LAUNCH_SESSION_RECORD_POLL_SECONDS,
          "each default comes from the module the launcher imports it from")
    check(m.os is os and m.subprocess is subprocess and m.Path is Path, "the standard-library names are the module's own")


def test_the_seams_read_through_the_launcher_and_nothing_bound() -> None:
    tree = ast.parse((ROOT / "scripts" / "switchyard_new_command.py").read_text(encoding="utf-8"))
    for name in FUNCTIONS:
        node = next(n for n in tree.body if getattr(n, "name", None) == name)
        through: dict[str, int] = {}
        for x in ast.walk(node):
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "launcher":
                through[x.attr] = through.get(x.attr, 0) + 1
        expected = SEAMS.get(name, {})
        check(through == expected, f"{name}: each launcher name read through it exactly as often as before: {through}")
        imports = [ast.unparse(x) for x in ast.walk(node) if isinstance(x, (ast.Import, ast.ImportFrom))]
        first = 1 if ast.get_docstring(node) is not None else 0
        check(imports == (["from scripts import team_launcher as launcher"] if expected else []) and (not expected or ast.unparse(node.body[first]) == imports[0]),
              f"{name}: the launcher imported first thing when it reads one, and nothing otherwise: {imports}")
        skip = {id(y) for part in [node.returns, *(a.annotation for a in node.args.args + node.args.kwonlyargs), *[d for d in node.args.kw_defaults if d]]
                if part is not None for y in ast.walk(part)}
        bare = sorted({x.id for x in ast.walk(node) if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in expected and id(x) not in skip})
        check(bare == [], f"{name}: none of them read past it: {bare}")
    top = [ast.unparse(n) for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    tc = [ast.unparse(n) for n in tree.body if isinstance(n, ast.If)]
    check(top == ["from __future__ import annotations", "import os", "import subprocess", "from pathlib import Path",
                  "from typing import TYPE_CHECKING, Any, Callable, Sequence", "from scripts.first_run_auth import NO_RUNNER_INJECTED",
                  "from scripts.layout_modes import LAYOUT_MODE_AUTO", "from scripts.new_project_precheck import _path_exists, _tcp_port_in_use",
                  "from scripts.session_records import LAUNCH_SESSION_RECORD_POLL_SECONDS, LAUNCH_SESSION_RECORD_TIMEOUT_SECONDS"]
          and tc == ["if TYPE_CHECKING:\n    from scripts.first_run_auth import _NoRunnerInjected"],
          f"the standard library, each default's own module, and the sentinel's type under TYPE_CHECKING: {top} {tc}")
    names = [n.name if isinstance(n, ast.FunctionDef) else n.targets[0].id for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))]
    check(names == list(MOVED), f"the command, and nothing else: {names}")


def test_the_launcher_reexports_it_and_its_dispatcher_reaches_it_there() -> None:
    tree = ast.parse((ROOT / "scripts" / "team_launcher.py").read_text(encoding="utf-8"))
    imports = [n for n in tree.body if isinstance(n, ast.ImportFrom) and n.module == "scripts.switchyard_new_command"]
    check(len(imports) == 1 and sorted(a.name for a in imports[0].names) == sorted(MOVED) and all(a.asname is None for a in imports[0].names),
          "one explicit import of exactly the command, unaliased")
    check(imports[0].lineno < min(n.lineno for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))),
          "at the top, above every definition and constant that could read them")
    defined = {getattr(n, "name", None) for n in tree.body} | {x.id for n in tree.body if isinstance(n, ast.Assign) for x in n.targets if isinstance(x, ast.Name)}
    # A neighbour stays reachable on the launcher: defined there, or -- once a later slice moves it on -- re-exported there, unaliased.
    exported = {a.name for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                for a in n.names if a.asname is None}
    check(not defined & set(MOVED) and {"switchyard_main", "provision_runtime_command", "report_installed_release_version",
                                        "_build_switchyard_new_parser", "_resolve_new_project_choices", "_check_new_project_preflight",
                                        "_prepare_new_project_accounts", "_prepare_new_project_board", "_run_new_project_sign_in",
                                        "_launch_new_project_panes", "NewProjectBoard", "NewProjectSignIn", "NO_RUNNER_INJECTED", "_NoRunnerInjected",
                                        "LAYOUT_MODE_AUTO", "LAUNCH_SESSION_RECORD_TIMEOUT_SECONDS", "LAUNCH_SESSION_RECORD_POLL_SECONDS",
                                        "_path_exists", "_tcp_port_in_use"} <= defined | exported,
          "the launcher defines none of them, and keeps its neighbours and every seam and default they read, its own or re-exported")
    uses: dict = {}
    for fn in tree.body:
        if isinstance(fn, (ast.FunctionDef, ast.ClassDef)):
            for x in ast.walk(fn):
                if isinstance(x, ast.Name) and x.id in MOVED:
                    uses.setdefault(fn.name, {}).setdefault(x.id, 0)
                    uses[fn.name][x.id] += 1
    check(uses == DISPATCH, f"switchyard_main dispatches new by its launcher global, exactly as often as before: {uses}")
    loose = sorted({x.id for n in tree.body if not isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Import, ast.ImportFrom)) for x in ast.walk(n)
                    if isinstance(x, ast.Name) and x.id in MOVED})
    check(loose == [], f"and nothing at module level reads them: {loose}")
    for path, uses in READERS.items():
        source = ast.parse((ROOT / path).read_text(encoding="utf-8"))
        got = sorted(ast.unparse(x) for x in ast.walk(source) if (isinstance(x, ast.Attribute) and x.attr in MOVED) or (isinstance(x, ast.Name) and x.id in MOVED))
        check(got == uses, f"{path} still reads them through the launcher: {got}")


# --- behaviour -----------------------------------------------------------------------------------------------------


def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def result(label):
        return GOLDEN[label]["result"]

    def phases(label):
        return [c[0] for c in GOLDEN[label]["calls"] if c[0] in PHASES]

    def kw(label, phase):
        return next(c[2] for c in GOLDEN[label]["calls"] if c[0] == phase)

    full = "new: every phase goes on, every argument given"
    check(phases(full) == list(PHASES) and result(full) == 0, "the six phases, in order, and the panes phase's answer is the command's")
    for label, stop in (("the board phase returns a status", 4), ("the board phase returns zero", 4), ("the sign-in phase returns a status", 5)):
        check(phases(f"new: {label}") == list(PHASES[:stop]) and isinstance(result(f"new: {label}"), int),
              f"{label}: returned as it came, nothing later runs")
    for label, stop in (("the choices phase refuses", 1), ("the preflight phase refuses", 2), ("the accounts phase refuses", 3)):
        check(phases(f"new: {label}") == list(PHASES[:stop]) and result(f"new: {label}")["raised"] == "SystemExit", f"{label}: the refusal reaches the caller")
    check(kw(full, "_check_new_project_preflight")["port_in_use"] == "RECORDER" and kw(full, "_prepare_new_project_board")["socket_exists"] == "RECORDER",
          "the port and socket probes given reach the preflight and board phases")
    default = "new: nothing given: every default"
    check(kw(default, "_check_new_project_preflight")["port_in_use"] == "CALLABLE scripts.new_project_precheck._tcp_port_in_use"
          and kw(default, "_prepare_new_project_board")["socket_exists"] == "CALLABLE scripts.new_project_precheck._path_exists"
          and kw(default, "_resolve_new_project_choices")["runner"] == "OBJECT scripts.first_run_auth._NoRunnerInjected"
          and kw(default, "_launch_new_project_panes")["session_record_timeout"] == 10.0 and kw(default, "_launch_new_project_panes")["layout_mode"] == "auto",
          "by default, the precheck's own probes, the no-runner sentinel, the session record timeout and the automatic layout")
    probes = "new: only the probes injected"
    check(kw(probes, "_launch_new_project_panes")["session_record_timeout"] == 0.5 and kw(probes, "_launch_new_project_panes")["session_record_poll"] == 0.125,
          "a session timeout and poll given reach the panes phase")
    check(kw(full, "_check_new_project_preflight")["runner"] == "resolve_new_project_choices.runner"
          and kw(full, "_launch_new_project_panes")["launch_runner"] == "run_new_project_sign_in.launch_runner"
          and kw(full, "_launch_new_project_panes")["config"] == "run_new_project_sign_in.config"
          and kw(full, "_prepare_new_project_accounts")["selected_role_clis"] == "check_new_project_preflight.selected_role_clis",
          "each phase gets what the earlier ones settled, the later value replacing the earlier")
    check(result("switchyard new, every option") == 0 and result("switchyard new, the board refuses") == 4
          and "switchyard_new_command" in [c[0] for c in GOLDEN["switchyard new, bare"]["calls"]], "switchyard new dispatches to the launcher's name")


def test_every_launcher_seam_is_reached() -> None:
    # The six phases are stood in on the launcher, recorded; the two continuation types are classes the command tests
    # with isinstance, so they stay the real ones -- one case rebinds a type on the launcher and one a phase, and
    # each changes the answer.
    names = {name for reads in SEAMS.values() for name in reads}
    types = {name for name in names if isinstance(getattr(t, name), type)}
    check(names - types <= REACHED and len(names - types) == 6, f"a recorder on the launcher reached every phase: missing {sorted(names - types - REACHED)}")
    rebound = {spec.get("rebind") for spec in CASES.values()} - {None}
    check(len(types) == 2 and rebound & types and rebound - types and "the rebound panes phase" in REACHED,
          f"and a type and a phase rebound there take effect: {sorted(rebound)}")


STRUCTURE = ("test_the_module_loads_only_where_its_defaults_come_from", "test_either_import_order_gives_one_object_and_the_launchers_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_it_and_its_dispatcher_reaches_it_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"switchyard_new_command_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
